    {"label": "Рис. 1.20", "unit_id": "u-038-f5b22f (подпись)", "role": "Палеопочва, венчающая прослой угля зарастающей дельты. Изображение разреза из скважины.", "redraw": false},
    {"label": "Рис. 1.21", "unit_id": "u-038-9b8596 (подпись)", "role": "Прослой угля, завершающий разрез зарастающего дельтового рукава. Изображение разреза из скважины.", "redraw": false}
  ],
